    const s = p.solid; const an = analyze(s);
    const vp = new Map(); const pt = (v) => { let r = vp.get(v); if (!r) { r = E(`CARTESIAN_POINT('',(${R(s.pos[v * 3])},${R(s.pos[v * 3 + 1])},${R(s.pos[v * 3 + 2])}))`); vp.set(v, r); } return r; };
